SI_MODULE_VERSION <- "1.0.0"
seurat_integrate_compute <- function(x,a) {
 batches <- strsplit(a[["batch-col"]],",",fixed=TRUE)[[1]]
 if(!all(batches %in% names(x[[]]))) os_seurat_fail("OS_MISSING_COLUMN","Missing explicit batch covariate.")
 assay <- x@misc$omicstat_state$assay
 reduction <- if(a$method=="HarmonyIntegration") os_seurat_option(a,"integrate-new-reduction","harmony") else "harmony"
 before <- SeuratObject::Embeddings(x[["umap"]]); x$cluster_unintegrated <- as.character(x$cluster)
 if(a$method=="RunHarmony") {
  x <- harmony::RunHarmony(object=x, reduction.use="pca", dims.use=seq_len(a$dims), reduction.save="harmony", project.dim=identical(a[["harmony-project-dim"]],"TRUE"), group.by.vars=batches, theta=a$theta, lambda=a$lambda, sigma=a$sigma, nclust=os_seurat_option(a,"harmony-nclust",NULL), max_iter=a[["max-iter"]], early_stop=os_seurat_option(a,"harmony-early-stop",TRUE), ncores=os_seurat_option(a,"harmony-ncores",1), verbose=FALSE, .options=harmony::harmony_options(alpha=os_seurat_option(a,"harmony-options-alpha",0.2), tau=os_seurat_option(a,"harmony-options-tau",0), block.size=os_seurat_option(a,"harmony-options-block-size",0.05), max.iter.cluster=os_seurat_option(a,"harmony-options-max-iter-cluster",4), epsilon.cluster=os_seurat_option(a,"harmony-options-epsilon-cluster",0.001), epsilon.harmony=os_seurat_option(a,"harmony-options-epsilon-harmony",0.01), batch.prop.cutoff=os_seurat_option(a,"harmony-options-batch-prop-cutoff",1e-05)))
 } else {
  if(length(batches)!=1L) os_seurat_fail("OS_INVALID_PARAMETER","HarmonyIntegration uses one explicit layer grouping column; RunHarmony supports multiple covariates.")
  if(assay!="RNA") os_seurat_fail("OS_INVALID_PARAMETER","Layer integration currently requires a LogNormalize RNA upstream; use RunHarmony for SCT.")
  x[[assay]] <- split(x[[assay]],f=x[[batches]][,1])
  x <- Seurat::IntegrateLayers(orig.reduction="pca", assay=assay, features=NULL, layers=NULL, scale.layer="scale.data", object=x, method=Seurat::HarmonyIntegration, new.reduction=reduction, theta=a$theta, lambda=a$lambda, sigma=a$sigma, nclust=os_seurat_option(a,"integrate-nclust",NULL), tau=os_seurat_option(a,"integrate-tau",0), block.size=os_seurat_option(a,"integrate-block-size",0.05), max.iter.harmony=a[["max-iter"]], max.iter.cluster=os_seurat_option(a,"integrate-max-iter-cluster",20L), epsilon.cluster=os_seurat_option(a,"integrate-epsilon-cluster",1e-5), epsilon.harmony=os_seurat_option(a,"integrate-epsilon-harmony",0.01), verbose=FALSE)
  x <- SeuratObject::JoinLayers(object=x,assay=assay,layers=NULL,new=NULL)
 }
 x <- Seurat::FindNeighbors(reduction=reduction, dims=seq_len(a$dims), assay=assay, features=NULL, k.param=a$neighbors, return.neighbor=FALSE, compute.SNN=TRUE, prune.SNN=os_seurat_option(a,"graph-prune-SNN",1/15), nn.method=os_seurat_option(a,"graph-nn-method","annoy"), n.trees=os_seurat_option(a,"graph-n-trees",50), annoy.metric=os_seurat_option(a,"graph-annoy-metric","euclidean"), nn.eps=os_seurat_option(a,"graph-nn-eps",0), verbose=FALSE, do.plot=FALSE, graph.name=c("integrated_nn","integrated_snn"), l2.norm=os_seurat_option(a,"graph-l2-norm",FALSE), cache.index=FALSE, object=x)
 x <- Seurat::FindClusters(graph.name="integrated_snn", cluster.name="cluster", modularity.fxn=os_seurat_option(a,"cluster-modularity-fxn",1), initial.membership=NULL, node.sizes=NULL, resolution=a$resolution, method=NULL, algorithm=os_seurat_option(a,"cluster-algorithm",1), leiden_method=os_seurat_option(a,"cluster-leiden-method",c("leidenbase", "igraph")), leiden_objective_function=os_seurat_option(a,"cluster-leiden-objective-function",c("modularity", "CPM")), n.start=os_seurat_option(a,"cluster-n-start",10), n.iter=os_seurat_option(a,"cluster-n-iter",10), random.seed=a$seed, group.singletons=os_seurat_option(a,"cluster-group-singletons",TRUE), temp.file.location=NULL, edge.file.name=NULL, verbose=FALSE, object=x)
 x <- Seurat::RunUMAP(dims=seq_len(a$dims), reduction=reduction, features=NULL, graph=NULL, assay=assay, nn.name=NULL, slot="data", umap.method=os_seurat_option(a,"umap-umap-method","uwot"), reduction.model=NULL, return.model=FALSE, n.neighbors=a[["umap-neighbors"]], n.components=os_seurat_option(a,"umap-n-components",2L), metric=os_seurat_option(a,"umap-metric","cosine"), n.epochs=os_seurat_option(a,"umap-n-epochs",NULL), learning.rate=os_seurat_option(a,"umap-learning-rate",1), min.dist=a[["min-dist"]], spread=os_seurat_option(a,"umap-spread",1), set.op.mix.ratio=os_seurat_option(a,"umap-set-op-mix-ratio",1), local.connectivity=os_seurat_option(a,"umap-local-connectivity",1L), repulsion.strength=os_seurat_option(a,"umap-repulsion-strength",1), negative.sample.rate=os_seurat_option(a,"umap-negative-sample-rate",5L), a=os_seurat_option(a,"umap-a",NULL), b=os_seurat_option(a,"umap-b",NULL), uwot.sgd=os_seurat_option(a,"umap-uwot-sgd",FALSE), uwot.approx_pow=os_seurat_option(a,"umap-uwot-approx-pow",FALSE), uwot.init=os_seurat_option(a,"umap-uwot-init","spectral"), seed.use=a$seed, metric.kwds=os_seurat_option(a,"umap-metric-kwds",NULL), angular.rp.forest=os_seurat_option(a,"umap-angular-rp-forest",FALSE), densmap=os_seurat_option(a,"umap-densmap",FALSE), dens.lambda=os_seurat_option(a,"umap-dens-lambda",2), dens.frac=os_seurat_option(a,"umap-dens-frac",0.3), dens.var.shift=os_seurat_option(a,"umap-dens-var-shift",0.1), verbose=FALSE, reduction.name="umap", reduction.key=NULL, object=x)
 st <- x@misc$omicstat_state; st$project.dim <- if(a$method=="RunHarmony") identical(a[["harmony-project-dim"]],"TRUE") else NULL; st$integrated <- TRUE; st$reduction <- reduction; st$integration_method <- a$method; st$batch_covariates <- batches; st$dims <- a$dims; st$resolution <- a$resolution
 coords <- SeuratObject::Embeddings(x[[reduction]])
 md <- data.frame(cell=colnames(x),x[[]],check.names=FALSE)
 tab <- as.data.frame(table(batch=interaction(x[[]][batches],drop=TRUE),cluster=x$cluster)); names(tab)[3] <- "n_cells"
 details <- sprintf("n=%d cells; harmony %s, route=%s, batch=%s, first %d PCs, sigma=%g, max_iter=%d, neighbor k=%d, resolution=%g; only the reduction is corrected; raw RNA is retained.",ncol(x),as.character(utils::packageVersion("harmony")),a$method,a[["batch-col"]],a$dims,a$sigma,a[["max-iter"]],a$neighbors,a$resolution)
 if(a$method=="RunHarmony") details <- paste(details,"Resolved RunHarmony project.dim =",st$project.dim)
 list(object=x,state=st,tables=list(cell_metadata=md,harmony=data.frame(cell=rownames(coords),coords),batch_clusters=tab),embeddings=list(before=before,after=SeuratObject::Embeddings(x[["umap"]])),details=details)
}
